"""
Shim for a broken FastAPI installation.

In a correct FastAPI wheel, `fastapi._compat` is a module (`_compat.py`).
In this environment, there is also a `fastapi/_compat/` package directory
that gets imported first and is missing required symbols (e.g. `PYDANTIC_V2`).

We load the sibling module file (`fastapi/_compat.py`) and re-export its public
attributes so imports like `from fastapi._compat import PYDANTIC_V2, ...` work.
"""

from __future__ import annotations

import importlib.util
from pathlib import Path
from types import ModuleType
from typing import Any


def _load_compat_module() -> ModuleType:
    compat_path = Path(__file__).resolve().parent.parent / "_compat.py"
    spec = importlib.util.spec_from_file_location("fastapi._compat_file", compat_path)
    if spec is None or spec.loader is None:
        raise ImportError(f"Cannot load FastAPI compat module from: {compat_path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)  # type: ignore[call-arg]
    return module


_m = _load_compat_module()
for _k, _v in _m.__dict__.items():
    if _k.startswith("__"):
        continue
    globals()[_k] = _v  # noqa: PLE0604

__all__ = [k for k in globals().keys() if not k.startswith("_") and k not in {"Any", "ModuleType"}]
